// UI language (English / Hindi / Arabic) and currency (INR / USD / USDT)
// support. Which languages and currencies a visitor can pick is controlled
// by the Admin in Settings → Language & Prices (settings switches); the
// App resolves the effective language/currency from those switches, with
// English as the language fallback and INR (or the first currency still
// ON) as the currency fallback.
// All money is stored server-side in integer INR. USD display converts at
// a fixed ₹83 = $1 and rounds the way Indian shoppers expect to see it:
// under $100 it shows a .99 price point, at $100+ a whole dollar. USDT is
// a DISPLAY price only, using the same store conversion (1 USDT ≈ $1,
// i.e. ₹83 = 1 USDT) and always shown with two decimals and Western
// digits, e.g. "USDT 18.07"; checkout, wallet balances and order totals
// keep their existing currency handling.
export type Lang = "en" | "hi" | "ar";
export type Currency = "INR" | "USD" | "USDT";

export const USD_RATE = 83;

export function formatMoney(inr: number, currency: Currency): string {
  if (currency === "INR") {
    return `₹${inr.toLocaleString("en-IN")}`;
  }
  if (currency === "USDT") {
    const v = inr / USD_RATE;
    return `USDT ${v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }
  const usd = inr / USD_RATE;
  if (usd >= 100) return `$${Math.round(usd).toLocaleString("en-US")}`;
  if (usd <= 0) return "$0";
  const point = Math.max(1, Math.round(usd)) - 0.01;
  return `$${point.toFixed(2)}`;
}

/** Convert a display-currency amount typed by the user back to integer INR. */
export function toInr(amount: number, currency: Currency): number {
  if (currency === "INR") return Math.round(amount);
  return Math.round(amount * USD_RATE);
}

// `ar` is optional per entry: the main visible UI strings carry a full
// Arabic translation; any string without one falls back to English when
// Arabic is selected (see tr below), never to a blank.
type Entry = { en: string; hi: string; ar?: string };

