  "fp.note": { en: "Note: Automatic email/SMS reset links will be enabled on the secure live version when an email/SMS service is connected. In this version, resets are completed by Customer Service as described above.", hi: "नोट: स्वचालित ईमेल/SMS रीसेट लिंक सुरक्षित लाइव संस्करण पर ईमेल/SMS सेवा जुड़ने पर चालू होंगे। इस संस्करण में रीसेट ऊपर बताए अनुसार ग्राहक सेवा द्वारा पूरे किए जाते हैं।" },
  "fp.identifierMissing": { en: "Please enter your Gmail or your 10-digit mobile number.", hi: "कृपया अपना Gmail या 10 अंकों का मोबाइल नंबर लिखें।" },
  "cp.tempNotice": { en: "You are using a password given by Customer Service. Please set your own password.", hi: "आप ग्राहक सेवा द्वारा दिया गया पासवर्ड उपयोग कर रहे हैं। कृपया अपना खुद का पासवर्ड सेट करें।" , ar: "أنت تستخدم كلمة مرور أعطتها خدمة العملاء. يرجى تعيين كلمة المرور الخاصة بك."},
