  "sord.historyCancelled": { en: "Cancelled — no payment or profit on this order.", hi: "रद्द — इस ऑर्डर पर कोई भुगतान या मुनाफ़ा नहीं।" },
  "aord.customersTitle": { en: "Customers with Orders", hi: "ऑर्डर वाले ग्राहक" , ar: "العملاء الذين لديهم طلبات"},
  "aord.customersSub": { en: "Orders are grouped by customer so nothing gets mixed up when there are many clients. Tap a customer to see only their orders, then approve and complete their deliveries from there.", hi: "ऑर्डर ग्राहक के हिसाब से अलग-अलग रखे गए हैं ताकि ज़्यादा ग्राहक होने पर कुछ गड़बड़ न हो। किसी ग्राहक पर दबाएँ — सिर्फ़ उसी के ऑर्डर दिखेंगे, वहीं से डिलीवरी मंज़ूर और पूरी करें।" , ar: "الطلبات مجمّعة حسب العميل حتى لا تختلط مع كثرة العملاء. اضغط على عميل لترى طلباته فقط، ثم وافق وأكمل تسليماته من هناك."},
