  "wp.confirmPay": { en: "Confirm — Pay & Withdraw", hi: "पुष्टि करें — भुगतान करें और निकालें" , ar: "تأكيد — ادفع واسحب"},
  "wp.paidOk": { en: "Withdrawal paid ✓ — new wallet balance:", hi: "निकासी का भुगतान हो गया ✓ — नया वॉलेट बैलेंस:" , ar: "تم دفع السحب ✓ — رصيد المحفظة الجديد:"},
