  "wp.realMoneyNote": { en: "The real money is paid by you outside this website (UPI / bank). This button records the payment here and deducts the amount from the customer's wallet — exactly once.", hi: "असली पैसा आप इस वेबसाइट के बाहर देते हैं (UPI / बैंक)। यह बटन यहाँ भुगतान दर्ज करता है और ग्राहक के वॉलेट से राशि काटता है — ठीक एक बार।" , ar: "يُدفع المال الحقيقي خارج هذا الموقع (UPI / البنك). هذا الزر يسجّل الدفع هنا ويخصم المبلغ من محفظة العميل — مرة واحدة بالضبط."},
  "wp.adminWithdraw": { en: "Admin Withdraw", hi: "एडमिन निकासी" , ar: "سحب المسؤول"},
  "wp.adminWithdrawSub": { en: "Withdraw an amount directly from this seller's wallet. It is deducted once, one ledger line is added, and the customer is notified with your note.", hi: "इस विक्रेता के वॉलेट से सीधे राशि निकालें। राशि एक बार कटेगी, खाते में एक लाइन जुड़ेगी, और ग्राहक को आपके नोट के साथ सूचना मिलेगी।" , ar: "اسحب مبلغًا مباشرة من محفظة هذا البائع. يُخصم مرة واحدة، ويُضاف سطر واحد في الدفتر، ويُبلَّغ العميل بملاحظتك."},
  "wp.noteReason": { en: "Note / Reason (required — customer sees it)", hi: "नोट / कारण (ज़रूरी — ग्राहक को दिखेगा)" , ar: "ملاحظة / سبب (مطلوب — يراه العميل)"},
  "wp.reviewWithdraw": { en: "Review & Confirm Withdrawal", hi: "निकासी देखें और पुष्टि करें" , ar: "مراجعة وتأكيد السحب"},
  "wp.confirmWithdraw": { en: "Confirm — Withdraw from Wallet", hi: "पुष्टि करें — वॉलेट से निकालें" , ar: "تأكيد — اسحب من المحفظة"},
