  "stmt.creditBreakdown": { en: "Deposits + Customer Service credit + completed order credits (full order value)", hi: "जमा + ग्राहक सेवा क्रेडिट + पूरे ऑर्डर के क्रेडिट (पूरा ऑर्डर मूल्य)" },
  "stmt.pendingNote": { en: "Pending — order payments held for orders in Shipment (still the seller's money; Total = Available + Pending). Deposit / withdrawal requests awaiting approval are separate and are not part of Pending", hi: "लंबित — शिपमेंट वाले ऑर्डर के लिए रुके ऑर्डर भुगतान (यह विक्रेता का ही पैसा है; कुल = उपलब्ध + लंबित)। मंज़ूरी के इंतज़ार वाले जमा / निकासी अनुरोध अलग हैं और लंबित में शामिल नहीं" },

  // Theme & Design (Admin → Settings)
