function entryText(entry: Entry, lang: Lang): string {
  if (lang === "ar") return entry.ar ?? entry.en;
  return entry[lang];
}

export function tr(lang: Lang, key: StrKey): string {
  if (lang === "ar") {
    const extra = AR_EXTRA[key as string];
    if (extra !== undefined && (STR[key] as Entry).ar === undefined) return extra;
  }
  return entryText(STR[key] as Entry, lang);
}

export function trCategory(lang: Lang, category: string): string {
  const key = `cat.${category}` as StrKey;
  if (!(key in STR)) return category;
  return entryText(STR[key] as Entry, lang);
}

export function trStatus(lang: Lang, status: string): string {
  const key = `status.${status}` as StrKey;
  if (!(key in STR)) return status;
  return entryText(STR[key] as Entry, lang);
}
